public sealed class ValidationBehavior<TReq, TRes>(IEnumerable<IValidator<TReq>> validators)
    : IPipelineBehavior<TReq, TRes> where TReq : notnull
{
    public async Task<TRes> Handle(TReq request, RequestHandlerDelegate<TRes> next,
        CancellationToken ct)
    {
        var errors = validators.Select(v => v.Validate(request))
            .SelectMany(r => r.Errors).ToList();
        if (errors.Count > 0) throw new ValidationException(errors); // przerwanie łańcucha
        return await next();                                       // następne ogniwo
    }
}

