public sealed class OutboxPublisher(IServiceScopeFactory scopes) : BackgroundService
{
    // Framework (BackgroundService.StartAsync) decyduje KIEDY; my tylko CO.
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        using var timer = new PeriodicTimer(TimeSpan.FromSeconds(5));
        while (await timer.WaitForNextTickAsync(stoppingToken))
        {
            using var scope = scopes.CreateScope();
            await scope.ServiceProvider.GetRequiredService<IOutbox>()
                .PublishPendingAsync(stoppingToken);
        }
    }
}

