public interface IPaymentGateway
{ Task<PaymentResult> ChargeAsync(Money amount, string token, CancellationToken ct); }

// Adapter driven (Infrastructure) – tłumaczy na SDK dostawcy
internal sealed class StripePaymentGateway(PaymentIntentService stripe) : IPaymentGateway
{
    public async Task<PaymentResult> ChargeAsync(Money a, string token, CancellationToken ct)
    {
        var intent = await stripe.CreateAsync(new() { Amount = a.ToMinorUnits(),
            Currency = a.Currency, PaymentMethod = token, Confirm = true }, cancellationToken: ct);
        return intent.Status == "succeeded" ? PaymentResult.Ok(intent.Id) : PaymentResult.Failed(intent.Status);
    }
}

